  "claude.tabApiKey": "APIキー",
  "claude.subscriptionIntro": "Pro、Max、Ultra プランでの利用をおすすめします。このサーバー（Claude Code はインストール済みです）から長期間有効なトークンを生成してください：",
  "claude.step1": "サーバーでターミナルを開きます（SSH）：",
  "claude.step2": "次のコマンドを実行し、表示されたリンクを開いて Claude アカウントでサインインして承認し、表示されたコードをターミナルに貼り付けてください：",
