  "claude.pasteFirst": "先にトークンを貼り付けてください。",
  "claude.authFailed": "Claude がこの認証情報を拒否しました。",
  "claude.connectTest": "接続してテスト",
  "claude.testing": "Claude にテストメッセージを送信中…",
  "cdef.defaultModel": "デフォルトモデル",
  "cdef.cliDefault": "Claude Code のデフォルト",
  "cdef.defaultModelHint": "セッションには、各ターンで実際に応答したモデルが表示されます。",
  "cdef.autoCompact": "自動コンパクト",
  "cdef.autoCompactHint": "ターン終了時のコンテキストがこのしきい値を超えると、Harness はセッションを要約し、その要約から始まる新しいスレッドで続行します（コンパクトと同様）。長いセッションが履歴全体を再送信しなくなるため、トークンを節約できます。履歴は表示されたままです。",
  "cdef.autoCompactOff": "オフ",
  "cdef.autoCompactRecommended": "推奨",
  "cdef.idleCompact": "戻ったときにコンパクト",
  "cdef.idleCompactHint": "Claude のプロンプトキャッシュは数分間（最長1時間）しか保持されません。それより長く放置されたセッションに、このコンテキスト以上の状態で書き込むと、Harness はまずセッションを要約し、あなたのメッセージは要約から始まる新しいスレッドで実行されます。履歴はどのみち通常料金で再送信されるため、以降のターンのコストが大きく下がります。返信の前に要約ターンが1回（短い待ち時間）かかります。",
  "cdef.smartResume": "スマート再開",
  "cdef.smartResumeHint": "キャッシュが切れたセッション（上記参照）にこのコンテキスト以上の状態で戻ったとき、または5分以上経過して2倍のコンテキストがあるとき、Harness はまず、いま送信したメッセージのために Claude にセッションを要約させます。要約にはメッセージに必要なもの（ファイル、コマンド、値、進行中の計画）が正確に残り、メッセージはずっと軽量な新しいスレッドで実行されます。実際の再開で計測したところ、100k以上でトークンが38〜67％減り、通常の要約より詳細もよく保たれました。オフ＝上記のルールのみ。",
  "cdef.protectSecrets": "シークレットを保護",
  "cdef.protectSecretsHint": "Claude のツールは、権限モードに関係なく、サーバーのシークレット（secrets.json）と SSH キー（~/.ssh）の読み取りや編集を拒否します。Web ページやメールに隠された指示によって単純に読み取られることを防ぎます。ファイルを開くために書かれたスクリプトは止められません。外部から来るコンテンツには、そのトピックでより厳格な権限モードを使うことをおすすめします。",
  "cdef.shortTitles": "短いセッションタイトル",
  "cdef.shortTitlesHint": "新しいセッションは、最初のメッセージから数語で名前が付けられます（挨拶や「〜してくれますか」は除きます）。オフ：タイトルはメッセージの冒頭になります。セッション名を変更した場合は常にそちらが優先されます。",
  "cdef.shortTitlesModel": "Claude が書くタイトル",
  "cdef.shortTitlesModelHint": "最小のモデルが話題を名付けます（より的確なタイトル）。新しいセッションごとに1回の簡単な呼び出しがあり、Claude プランの利用量に含まれます。",
  "pbox.mode": "サンドボックス（このトピックのみ）",
  "pbox.modeDesc": "Claude はトピックのフォルダ内で、確認なしに自由に作業します。コマンドはそこにのみ書き込み、サーバーのキーやホームフォルダは読み取れません。外に出る必要があること（パッケージのインストール、サービスの再起動、別のフォルダ）は、まず確認が表示され、トピックにフルアクセスを与えるボタンも表示されます。",
  "cdef.autoUpdate": "Claude Code を自動更新",
  "cdef.autoUpdateHint": "デフォルトではオフです。オンの場合：Claude Code の新しい安定版が公開されると（すでに数日間使われているもので、最新版そのものではありません）、10分間何も実行されていない状態（ターン、待機中のメッセージ、定期ジョブがない）になり次第サーバーがインストールし、起動しない場合は前のバージョンに戻します。6時間ごとに確認され、結果は通知に表示されます。",
  "cdef.autoUpdateLast": "最終更新：{from} → {to}、{date}",
  "cdef.autoUpdateFailed": "{to} への更新に失敗しました（{date}）",
  "claude.permissionMode": "権限モード",
  "claude.mode.bypass": "フルアクセス（権限をバイパス）",
  "claude.mode.bypassDesc": "Claude は確認なしに任意のコマンドを実行し、任意のファイルを編集します。サービスユーザー（root）の権限で動作します。このサーバーが Claude 専用の場合にのみ選択してください。",
  "claude.mode.recommendedVps": "専用 VPS のみ",
  "claude.mode.acceptEdits": "ファイル編集を許可",
  "claude.mode.acceptEditsDesc": "Claude はファイルの読み書きができます。承認が必要なその他のツール（ほとんどのシェルコマンド）は拒否されます。",
  "claude.mode.default": "厳格（拒否）",
  "claude.mode.defaultDesc": "承認が必要なツールはすべて、確認なしに拒否されます。最も安全ですが、Claude にできることはかなり少なくなります。",
  "claude.mode.ask": "確認する",
