  "infra.mail.f.dmarc_none": "あなたの名義で送信するすべてのサービスで SPF と DKIM が通るようになったら、p=quarantine に、その後 p=reject に切り替えてください。",
  "infra.mail.p.dmarc_inherited": "{domain} に DMARC レコードがありません。{parent} のポリシーが適用されます（p={policy}）。",
  "infra.mail.f.dmarc_inherited": "追加は不要です。ここに p=none のレコードを追加しないでください。このドメインのポリシーが弱くなります。",
  "infra.mail.p.dmarc_inherited_none": "{domain} に DMARC レコードがありません。{parent} のポリシーが適用されます（p=none）。",
  "infra.mail.f.dmarc_inherited_none": "SPF と DKIM が通るようになったら、{parent} のレコードを p=quarantine に、その後 p=reject に切り替えてください。",
  "infra.mail.p.spf_neutral": "{domain} の SPF レコードが ~all も -all も終わっていません。他の送信元について何も定めていないため、誰でも @{domain} を名乗ってメールを送信できてしまいます。",
  "infra.mail.f.spf_neutral": "末尾を ~all（または -all）にしてください。",
  "infra.mail.p.dmarc_inherited_sp": "{domain} に DMARC レコードがありません。{parent} はサブドメインに sp=none を設定しているため、{parent} の p= に関係なく {domain} は p=none になります。",
  "infra.mail.f.dmarc_inherited_sp": "{domain} で SPF と DKIM が通るようになったら、{parent} のレコードで sp=none を sp=quarantine に、その後 sp=reject に変更するか、{domain} に p=quarantine の独自レコード _dmarc.{domain} を用意してください。{parent} の p= は下げないでください。",
  "infra.mail.p.dmarc_inherited_sp_quarantine": "{domain} に DMARC レコードがありません。{parent} は p={parent_policy} ですが、サブドメインには sp={policy} を設定しているため、{domain} は p={policy} になります。",
  "infra.mail.f.dmarc_inherited_sp_quarantine": "{domain} にも p={parent_policy} を適用するには、{parent} のレコードで sp={policy} を sp={parent_policy} に変更する（または sp= を削除する）か、{domain} に p={parent_policy} の独自レコード _dmarc.{domain} を用意してください。{parent} の p= は下げないでください。",
  "infra.mail.p.dmarc_parent_invalid": "{domain} に DMARC レコードがなく、{parent} のレコードも無効です（{reason}）。{domain} に適用される DMARC ポリシーはありません。",
  "infra.mail.f.dmarc_parent_invalid": "レコード _dmarc.{parent} を修正する（p= を含む v=DMARC1 の TXT レコードを 1 件だけにする）か、TXT レコード _dmarc.{domain} を追加してください：{record}",
  "infra.mail.p.spf_redirect_all": "{domain} の SPF レコードは {target} に委ねられており（redirect=）、そちらが +all で終わっています。誰でも @{domain} として送信できます。",
  "infra.mail.f.spf_redirect_all": "{domain} のレコードを redirect= ではなく ~all で終わらせるか、{target} を修正してください。",
  "infra.mail.p.spf_loop": "{domain} の SPF レコードがループしています。{target} がチェーン内にある既存のレコードに戻っており、受信側はこれをエラーとして扱います。",
  "infra.mail.f.spf_loop": "チェーン内にある既存のレコードに戻っている include: または redirect= を削除してください。",
  "infra.mail.p.no_spf_sender": "SPF レコードがありません。誰でも @{domain} を名乗ってメールを送信できてしまいます。",
  "infra.mail.f.no_spf_sender": "送信に使うすべてのサービスを指定した TXT レコードを {domain} に追加してください。{record} をベースに、~all の前に {sender} の include: を追加します（プロバイダーのドキュメントに記載されています）。",
  "infra.mail.p.no_spf_unknown": "SPF レコードがありません。誰でも @{domain} を名乗ってメールを送信できてしまいます。",
  "infra.mail.f.no_spf_unknown": "{domain} に、メール送信に使うすべてのサービスを指定する TXT レコードを追加してください。MX レコードだけから判断すると {record} になります。~all の前に、送信に使うサービスの include:（メールプロバイダーの案内に記載されています）を追加してください。追加しないと、送信したメールは SPF に失敗します。",
