  "system.cleanup.previewsDesc": "プレーヤー用の軽量な動画コピーとファイルのサムネイル：表示時に再作成されます（多少の処理負荷があります）。過去30分以内に再生された動画は残ります。",
  "system.cleanup.trash": "Harness のゴミ箱",
  "system.cleanup.trashDesc": "削除したトピック、セッション、ファイル：後から復元できなくなります。",
  "system.cleanupPrompt": "このサーバーのディスク容量を監査し、きちんと解放できるよう手伝ってください。\n\n1. 状態：`df -h` と `free -h`、続いて大きいフォルダー（`du -xh --max-depth=2 / 2>/dev/null | sort -h | tail -40`）を確認し、特に大きいものを掘り下げてください。設定 → システム → 容量を解放 では、ダウンロードキャッシュ、古いコンポーネントのバージョン、システムジャーナル、apt パッケージ、動画プレビュー、Harness のゴミ箱をすでに処理しているので、それらは除外してください。\n2. ワークスペースのすべてのプロジェクトとトピックを確認してください：添付ファイル、動画・音声のレンダリング結果、エクスポート、`node_modules`、Python 環境、ビルド、大きな git リポジトリ、忘れられた別コピー、重複ファイル。他のツールのキャッシュ（`~/.cache/*`、ダウンロード済みモデル）、ログ、`/tmp` 内の古いファイルも確認してください。\n3. 大きなものごとに、出所を突き止めてください：どのプロジェクト、ツール、定期ジョブが作成したのか（日付、内容、トピックのメモリ、cron）、まだ増え続けているかどうか。\n4. サイズ順の表を出してください：パス、サイズ、出所、自動で戻るかどうか、提案（削除、別の場所へ移動、保持）、解放できる容量。\n5. 私の了承なしに何も削除しないでください：質問はすべてまとめて聞いてください。何度も戻ってくるものについては、原因の修正（サイズ制限、それを生成するスクリプトやジョブ内での整理）を提案してください。\n6. 最後に、決まったこと（残すもの、整理するもの）を適切なトピックのメモリに書き留めてください。",
