  "groups.claude.create": "スキル maxxing-agents を使って、プロジェクト {project} にエージェントグループを作成してください。足りない情報（どのエージェントか、グループの目的）だけ質問し、その後 `maxxing agents group create` で作成してください。\n\nこのグループの目的：",
  "groups.claude.createWith": "スキル maxxing-agents を使って、プロジェクト {project} に {agents} でエージェントグループを作成してください。足りない情報（グループの目的）だけ質問し、その後 `maxxing agents group create` で作成してください。\n\nこのグループの目的：",
  "groups.claude.createAny": "スキル maxxing-agents を使って、エージェントグループを作成してください。足りない情報（プロジェクト、エージェント、グループの目的）だけ質問し、その後 `maxxing agents group create` で作成してください。\n\nこのグループの目的：",
  "groups.claude.edit": "エージェントグループ「{name}」を変更してください。{path} の CLAUDE.md（目的）または group.json（メンバー、役割、リーダー、オプション）を編集します。私が頼んだ箇所だけ変更し、その後、変更内容を要約してください。\n\n変更したい内容：",
