  "devices.feature.enable": "自分のデバイスを使う",
  "devices.feature.enableDesc": "Harness Linkアプリでパソコン（Windows、Mac、Linux）またはAndroidスマートフォンを接続します。セッションは許可したデバイスを使えます。エージェントは、そのエージェント用にオンにしたデバイスのみ使えます。",
